@app.post("/api/v1/publish-editorial")
async def publish_editorial(req: EditorialReq, db: DBWrapper = Depends(get_db)):
    db.execute("CREATE TABLE IF NOT EXISTS editorial (ed_id TEXT PRIMARY KEY, category TEXT, title TEXT, summary TEXT, author TEXT, ts INTEGER);")
    row = db.execute("SELECT admin_pin FROM settings WHERE id=1").fetchone()
    valid_pin = row.__getitem__(0) if row else "1234"
    if req.pin != valid_pin:
        raise HTTPException(status_code=403, detail="Invalid Admin PIN")
    eid = f"ED-{int(time.time()) % 100000}"
    db.execute("INSERT INTO editorial VALUES (?, ?, ?, ?, ?, ?)", (eid, req.category, req.title, req.summary, req.author, int(time.time())))
    db.commit()
    send_telegram_alert(f"✍️ NEW EDITORIAL PUBLISHED ({eid})!\n• Category: {req.category}\n• Title: {req.title}")
    return {"message": f"Published {eid} live on /editorial!"}

class AdminActionReq(BaseModel):
    pin: str
    kind: str
    item_id: str
    action: str

@app.get("/api/v1/backup.json")
async def export_full_backup(pin: str = "", db: DBWrapper = Depends(get_db)):
    row = db.execute("SELECT admin_pin FROM settings WHERE id=1").fetchone()
    valid_pin = row.__getitem__(0) if row else "1234"
    if pin != valid_pin:
        raise HTTPException(status_code=403, detail="Invalid Admin PIN")
    tables = ["ad_campaigns", "impressions", "clicks", "tenders", "deposits", "careers", "editorial", "wac_mail", "settings"]
    dump = {"exported_at": int(time.time()), "service": "Worldwide Ad Center", "tables": {}}
    for tb in tables:
        try:
            rows = db.execute(f"SELECT * FROM {tb}").fetchall()
            dump["tables"][tb] = [list(r) for r in rows]
        except Exception:
            dump["tables"][tb] = list()
    return Response(content=json.dumps(dump, indent=2, default=str), media_type="application/json", headers={"Content-Disposition": "attachment; filename=wac_full_backup.json"})

@app.post("/api/v1/restore-backup")
async def restore_full_backup(req: dict, db: DBWrapper = Depends(get_db)):
    row = db.execute("SELECT admin_pin FROM settings WHERE id=1").fetchone()
    valid_pin = row.__getitem__(0) if row else "1234"
    if req.get("pin") != valid_pin:
        raise HTTPException(status_code=403, detail="Invalid Admin PIN")
    tables = req.get("tables", {})
    restored = 0
    for tb, rows in tables.items():
        if not rows or tb not in ["ad_campaigns", "tenders", "deposits", "careers", "editorial", "wac_mail"]:
            continue
        for r in rows:
            try:
                ph = ",".join(["?"] * len(r))
                db.execute(f"INSERT OR IGNORE INTO {tb} VALUES ({ph})", tuple(r))
                restored += 1
            except Exception:
                try:
                    ph = ",".join(["?"] * len(r))
                    db.execute(f"INSERT INTO {tb} VALUES ({ph}) ON CONFLICT DO NOTHING", tuple(r))
                    restored += 1
                except Exception:
                    pass
    db.commit()
    return {"message": f"Restored {restored} records safely into database!"}

@app.post("/api/v1/admin-action")
async def admin_action(req: AdminActionReq, db: DBWrapper = Depends(get_db)):
    row = db.execute("SELECT admin_pin FROM settings WHERE id=1").fetchone()
    valid_pin = row.__getitem__(0) if row else "1234"
    if req.pin != valid_pin:
        raise HTTPException(status_code=403, detail="Invalid Admin PIN")
    if req.kind == "ad":
        if req.action == "approve":
            db.execute("UPDATE ad_campaigns SET active=1 WHERE CAST(id AS TEXT)=?", (req.item_id,))
        elif req.action == "pause":
            db.execute("UPDATE ad_campaigns SET active=0 WHERE CAST(id AS TEXT)=?", (req.item_id,))
        elif req.action == "delete":
            db.execute("DELETE FROM ad_campaigns WHERE CAST(id AS TEXT)=?", (req.item_id,))
    elif req.kind == "tender":
        if req.action == "approve":
            db.execute("UPDATE tenders SET approved=1 WHERE tender_id=?", (req.item_id,))
        elif req.action == "delete":
            db.execute("DELETE FROM tenders WHERE tender_id=?", (req.item_id,))
    elif req.kind == "career":
        db.execute("DELETE FROM careers WHERE app_id=?", (req.item_id,))
    db.commit()
    return {"message": f"Action '{req.action}' completed on {req.kind.upper()} #{req.item_id}!"}

class RoadmapReq(BaseModel):
    pin: str
    branch: str
    title: str

@app.post("/api/v1/roadmap/add")
async def add_roadmap_item(req: RoadmapReq, db: DBWrapper = Depends(get_db)):
    row = db.execute("SELECT admin_pin FROM settings WHERE id=1").fetchone()
    valid_pin = row.__getitem__(0) if row else "1234"
    if req.pin != valid_pin:
        raise HTTPException(status_code=403, detail="Invalid Admin PIN")
    db.execute("CREATE TABLE IF NOT EXISTS wac_roadmap (item_id TEXT PRIMARY KEY, branch TEXT, title TEXT, ts INTEGER);")
    iid = f"RM-{int(time.time()) % 100000}"
    db.execute("INSERT INTO wac_roadmap VALUES (?, ?, ?, ?)", (iid, req.branch, req.title, int(time.time())))
    db.commit()
    return {"message": f"Added '{req.title}' to {req.branch}!"}

