def make_qr_b64(data_str: str) -> str:
    try:
        img = qrcode.make(data_str, image_factory=qrcode.image.svg.SvgPathImage, box_size=8, border=2)
        buf = io.BytesIO()
        img.save(buf)
        return "data:image/svg+xml;base64," + base64.b64encode(buf.getvalue()).decode()
    except Exception:
        return ""

def get_live_proof(db: DBWrapper) -> str:
    imp_c = db.execute("SELECT COUNT(*) FROM impressions").fetchone().__getitem__(0)
    clk_c = db.execute("SELECT COUNT(*) FROM clicks").fetchone().__getitem__(0)
    cmp_c = db.execute("SELECT COUNT(*) FROM ad_campaigns WHERE active=1").fetchone().__getitem__(0)
    tnd_c = db.execute("SELECT COUNT(*) FROM tenders WHERE approved=1").fetchone().__getitem__(0)
    return f'<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin:12px 0;"><div style="background:#0f172a;padding:10px;border-radius:8px;text-align:center;border:1px solid #38bdf8;"><div style="font-size:18px;font-weight:bold;color:#38bdf8;">{imp_c:,}</div><small style="color:#94a3b8;font-size:10px;">VERIFIED IMPRESSIONS</small></div><div style="background:#0f172a;padding:10px;border-radius:8px;text-align:center;border:1px solid #22c55e;"><div style="font-size:18px;font-weight:bold;color:#22c55e;">{clk_c:,}</div><small style="color:#94a3b8;font-size:10px;">HUMAN CLICKS (GUARDED)</small></div><div style="background:#0f172a;padding:10px;border-radius:8px;text-align:center;border:1px solid #ec4899;"><div style="font-size:18px;font-weight:bold;color:#ec4899;">{cmp_c}</div><small style="color:#94a3b8;font-size:10px;">ACTIVE AD CAMPAIGNS</small></div><div style="background:#0f172a;padding:10px;border-radius:8px;text-align:center;border:1px solid #f59e0b;"><div style="font-size:18px;font-weight:bold;color:#f59e0b;">{tnd_c}</div><small style="color:#94a3b8;font-size:10px;">LIVE GLOBAL &amp; NEPAL TENDERS</small></div></div>'

